-- Product-level Size / Sugar / Ice / Toppings customization
USE milk_tea_pos;
ALTER TABLE products ADD COLUMN IF NOT EXISTS allow_size TINYINT(1) NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS allow_sugar TINYINT(1) NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS allow_ice TINYINT(1) NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS allow_toppings TINYINT(1) NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS size_options TEXT NULL, ADD COLUMN IF NOT EXISTS topping_options TEXT NULL;
ALTER TABLE transaction_details ADD COLUMN IF NOT EXISTS selected_size VARCHAR(80) NULL, ADD COLUMN IF NOT EXISTS toppings TEXT NULL, ADD COLUMN IF NOT EXISTS customization_price DECIMAL(10,2) NOT NULL DEFAULT 0.00;
ALTER TABLE customer_cart_items ADD COLUMN IF NOT EXISTS selected_size VARCHAR(80) NULL, ADD COLUMN IF NOT EXISTS toppings TEXT NULL, ADD COLUMN IF NOT EXISTS variant_key CHAR(64) NULL;
